class DataType(typing.Generic[T]):
    def __init__(self, value: T):
        self._value = value

    @property
    def value(self) -> T:
        return self._value

    def __repr__(self):
        return f"{self.__class__.__name__}({self._value!r})"

    def __eq__(self, other):
        if isinstance(other, DataType):
            return self._value == other._value
        return self._value == other

    def __hash__(self):
        return hash(self._value)

class String(DataType[str]):
    def __init__(self, value: str, encoding: str = 'utf-8'):
        if not isinstance(value, str):
            raise ValidationError(f"Expected str, got {type(value)}")
        super().__init__(value)
        self._encoding = encoding

    def to_bytes(self) -> bytes:
        return self._value.encode(self._encoding)

    @classmethod
    def from_bytes(cls, data: bytes, encoding: str = 'utf-8') -> 'String':
        return cls(data.decode(encoding))

class Integer(DataType[int]):
    def __init__(self, value: int, min_val: int = None, max_val: int = None):
        if not isinstance(value, int):
            raise ValidationError(f"Expected int, got {type(value)}")
        if min_val is not None and value < min_val:
            raise ValidationError(f"Value {value} is less than minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValidationError(f"Value {value} is greater than maximum {max_val}")
        super().__init__(value)

class Float(DataType[float]):
    def __init__(self, value: float, min_val: float = None, max_val: float = None):
        if not isinstance(value, (int, float)):
            raise ValidationError(f"Expected float, got {type(value)}")
        float_val = float(value)
        if min_val is not None and float_val < min_val:
            raise ValidationError(f"Value {float_val} is less than minimum {min_val}")
        if max_val is not None and float_val > max_val:
            raise ValidationError(f"Value {float_val} is greater than maximum {max_val}")
        super().__init__(float_val)

class Boolean(DataType[bool]):
    def __init__(self, value: bool):
        if not isinstance(value, bool):
            raise ValidationError(f"Expected bool, got {type(value)}")
