class List(DataType[typing.List[T]]):
    def __init__(self, value: typing.List[T], item_type: typing.Type[T] = None):
        if not isinstance(value, list):
            raise ValidationError(f"Expected list, got {type(value)}")
        if item_type is not None:
            for i, item in enumerate(value):
                if not isinstance(item, item_type):
                    raise ValidationError(f"Item at index {i} is not of type {item_type}")
        super().__init__(value)

class Dictionary(DataType[typing.Dict[str, T]]):
    def __init__(self, value: typing.Dict[str, T], value_type: typing.Type[T] = None):
        if not isinstance(value, dict):
            raise ValidationError(f"Expected dict, got {type(value)}")
        if value_type is not None:
            for key, val in value.items():
                if not isinstance(key, str):
                    raise ValidationError(f"Key {key} is not a string")
                if not isinstance(val, value_type):
                    raise ValidationError(f"Value for key {key} is not of type {value_type}")
        super().__init__(value)

