class Hash(DataType[str]):
    ALGORITHMS = ['md5', 'sha1', 'sha224', 'sha256', 'sha384', 'sha512', 'blake2b', 'blake2s', 'sha3_224', 'sha3_256', 'sha3_384', 'sha3_512', 'shake_128', 'shake_256']

    def __init__(self, value: str, algorithm: str = 'sha256'):
        if algorithm not in self.ALGORITHMS:
            raise ValidationError(f"Unsupported hash algorithm: {algorithm}")
        if not isinstance(value, str):
            raise ValidationError(f"Expected hex string, got {type(value)}")
        super().__init__(value)
        self._algorithm = algorithm

    @classmethod
    def compute(cls, data: bytes, algorithm: str = 'sha256') -> 'Hash':
        hasher = hashlib.new(algorithm)
        hasher.update(data)
        return cls(hasher.hexdigest(), algorithm)

