class Event(typing.Generic[T]):
    _handlers: typing.List[typing.Callable[[T], None]] = []

    def __init__(self):
        self._handlers = []

    def subscribe(self, handler: typing.Callable[[T], None]):
        self._handlers.append(handler)
        return self

    def unsubscribe(self, handler: typing.Callable[[T], None]):
        if handler in self._handlers:
            self._handlers.remove(handler)
        return self

    def emit(self, payload: T):
        for handler in self._handlers:
            try:
                handler(payload)
            except Exception as e:
                pass

    def __iadd__(self, handler: typing.Callable[[T], None]):
        self.subscribe(handler)
        return self

    def __isub__(self, handler: typing.Callable[[T], None]):
        self.unsubscribe(handler)
        return self

class EventBus:
    def __init__(self):
        self._events: typing.Dict[str, Event] = {}
        self._lock = threading.RLock()

    def get_event(self, name: str) -> Event:
        with self._lock:
            if name not in self._events:
                self._events[name] = Event()
            return self._events[name]

    def emit(self, name: str, payload: typing.Any = None):
        event = self.get_event(name)
        event.emit(payload)

    def subscribe(self, name: str, handler: typing.Callable):
        event = self.get_event(name)
        event.subscribe(handler)

    def unsubscribe(self, name: str, handler: typing.Callable):
        event = self.get_event(name)
        event.unsubscribe(handler)

    def clear(self):
        with self._lock:
            self._events.clear()

class ConfigManager:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(ConfigManager, cls).__new__(cls)
            cls._instance._config = {}
            cls._instance._sources = []
            cls._instance._watchers = []
            cls._instance._lock = threading.RLock()
        return cls._instance

    def add_source(self, source: typing.Dict[str, typing.Any]):
        with self._lock:
            self._sources.append(source)
            self._reload()

    def _reload(self):
        merged = {}
        for source in reversed(self._sources):
            merged.update(source)
        self._config = merged

    def get(self, key: str, default: typing.Any = None) -> typing.Any:
        keys = key.split('.')
        value = self._config
        for k in keys:
            if isinstance(value, dict) and k in value:
                value = value[k]
            else:
                return default
        return value

    def set(self, key: str, value: typing.Any):
        with self._lock:
            keys = key.split('.')
            current = self._config
            for k in keys[:-1]:
                if k not in current:
                    current[k] = {}
                current = current[k]
            current[keys[-1]] = value
            self._notify_watchers(key, value)

    def _notify_watchers(self, key: str, value: typing.Any):
        for watcher in self._watchers:
            watcher(key, value)

    def watch(self, callback: typing.Callable[[str, typing.Any], None]):
        self._watchers.append(callback)

    def get_all(self) -> typing.Dict[str, typing.Any]:
        return dict(self._config)

class Logger:
    _levels = {'DEBUG': 10, 'INFO': 20, 'WARNING': 30, 'ERROR': 40, 'CRITICAL': 50}
    _loggers: typing.Dict[str, logging.Logger] = {}
    _lock = threading.Lock()

    @classmethod
    def get_logger(cls, name: str) -> logging.Logger:
        with cls._lock:
            if name not in cls._loggers:
                logger = logging.getLogger(name)
                logger.setLevel(logging.DEBUG)
                if not logger.handlers:
                    handler = logging.StreamHandler(sys.stdout)
                    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
                    handler.setFormatter(formatter)
                    logger.addHandler(handler)
                cls._loggers[name] = logger
            return cls._loggers[name]

    @classmethod
    def set_level(cls, level: str):
        log_level = cls._levels.get(level.upper(), logging.INFO)
        for logger in cls._loggers.values():
            logger.setLevel(log_level)

class DependencyContainer:
    def __init__(self):
        self._services: typing.Dict[typing.Type, typing.Any] = {}
        self._factories: typing.Dict[typing.Type, typing.Callable] = {}
        self._singletons: typing.Dict[typing.Type, typing.Any] = {}
        self._lock = threading.RLock()

    def register(self, interface: typing.Type, implementation: typing.Any = None, factory: typing.Callable = None, singleton: bool = True):
        with self._lock:
            if factory:
                self._factories[interface] = factory
            elif implementation:
                if singleton:
                    self._singletons[interface] = implementation
                else:
                    self._services[interface] = implementation
            else:
                raise ConfigurationError("Must provide either implementation or factory")

    def resolve(self, interface: typing.Type) -> typing.Any:
        with self._lock:
            if interface in self._singletons:
                return self._singletons[interface]
            elif interface in self._services:
                return self._services[interface]
            elif interface in self._factories:
                instance = self._factories[interface](self)
                if hasattr(self._factories[interface], '_singleton') and self._factories[interface]._singleton:
                     self._singletons[interface] = instance
                return instance
            else:
                if inspect.isclass(interface) and not inspect.isabstract(interface):
                    try:
                        return self._auto_wire(interface)
                    except Exception as e:
                        raise DependencyInjectionError(f"Cannot resolve {interface.__name__}: {e}")
                raise DependencyInjectionError(f"Service {interface.__name__} not registered")

    def _auto_wire(self, cls: typing.Type) -> typing.Any:
        signature = inspect.signature(cls.__init__)
        args = {}
        for name, param in signature.parameters.items():
            if name == 'self':
                continue
            if param.annotation != inspect.Parameter.empty:
                args[name] = self.resolve(param.annotation)
            else:
                raise DependencyInjectionError(f"Cannot auto-wire parameter '{name}' of {cls.__name__} without type annotation")
        return cls(**args)

class State:
    def __init__(self, initial_state: str = 'initial'):
        self._state = initial_state
        self._transitions: typing.Dict[str, typing.Set[str]] = {}
        self._callbacks: typing.Dict[str, typing.List[typing.Callable]] = {}
        self._lock = threading.RLock()

    def add_transition(self, from_state: str, to_state: str):
        if from_state not in self._transitions:
            self._transitions[from_state] = set()
        self._transitions[from_state].add(to_state)

    def add_callback(self, state: str, callback: typing.Callable):
        if state not in self._callbacks:
            self._callbacks[state] = []
        self._callbacks[state].append(callback)

    def transition(self, to_state: str):
        with self._lock:
            if self._state in self._transitions and to_state in self._transitions[self._state]:
                old_state = self._state
                self._state = to_state
                if to_state in self._callbacks:
                    for cb in self._callbacks[to_state]:
                        cb(old_state, to_state)
            else:
                raise StateMachineError(f"Invalid transition from {self._state} to {to_state}")

    def get_state(self) -> str:
        return self._state

class Serializer:
    _serializers: typing.Dict[typing.Type, typing.Callable[[typing.Any], str]] = {}
    _deserializers: typing.Dict[typing.Type, typing.Callable[[str], typing.Any]] = {}

    @classmethod
    def register(cls, type_cls: typing.Type, serializer: typing.Callable, deserializer: typing.Callable):
        cls._serializers[type_cls] = serializer
        cls._deserializers[type_cls] = deserializer

    @classmethod
    def serialize(cls, obj: typing.Any) -> str:
        obj_type = type(obj)
        if obj_type in cls._serializers:
            return cls._serializers[obj_type](obj)
        elif hasattr(obj, 'to_json'):
            return obj.to_json()
        else:
            try:
                return json.dumps(obj)
            except TypeError:
                raise SerializationError(f"Cannot serialize object of type {obj_type}")

    @classmethod
    def deserialize(cls, data: str, type_cls: typing.Type) -> typing.Any:
        if type_cls in cls._deserializers:
            return cls._deserializers[type_cls](data)
        elif hasattr(type_cls, 'from_json'):
            return type_cls.from_json(data)
        else:
            try:
                return json.loads(data)
            except json.JSONDecodeError:
                raise SerializationError(f"Cannot deserialize data to type {type_cls}")

class Cryptography:
    @staticmethod
    def generate_random_bytes(length: int) -> bytes:
        return secrets.token_bytes(length)

    @staticmethod
    def generate_random_string(length: int) -> str:
        return secrets.token_urlsafe(length)

    @staticmethod
    def hash_password(password: str, salt: bytes = None) -> tuple:
        if salt is None:
            salt = Cryptography.generate_random_bytes(16)
        if isinstance(password, str):
            password = password.encode('utf-8')
        dk = hashlib.pbkdf2_hmac('sha256', password, salt, 100000)
        return (dk, salt)

    @staticmethod
    def verify_password(password: str, hashed: bytes, salt: bytes) -> bool:
        new_hash, _ = Cryptography.hash_password(password, salt)
        return hmac.compare_digest(new_hash, hashed)

    @staticmethod
    def encrypt(data: bytes, key: bytes) -> bytes:
        if len(key) not in [16, 24, 32]:
            raise EncryptionError("Key must be 16, 24, or 32 bytes long")
        iv = Cryptography.generate_random_bytes(16)
        cipher = Crypto.Cipher.AES.new(key, Crypto.Cipher.AES.MODE_CBC, iv)
        padded_data = Cryptography._pad(data)
        encrypted = cipher.encrypt(padded_data)
        return iv + encrypted

    @staticmethod
    def decrypt(encrypted_data: bytes, key: bytes) -> bytes:
        if len(key) not in [16, 24, 32]:
            raise EncryptionError("Key must be 16, 24, or 32 bytes long")
        iv = encrypted_data[:16]
        cipher = Crypto.Cipher.AES.new(key, Crypto.Cipher.AES.MODE_CBC, iv)
        padded_data = cipher.decrypt(encrypted_data[16:])
        return Cryptography._unpad(padded_data)

    @staticmethod
    def _pad(data: bytes) -> bytes:
        pad_len = 16 - (len(data) % 16)
        return data + bytes([pad_len]) * pad_len

    @staticmethod
    def _unpad(data: bytes) -> bytes:
        pad_len = data[-1]
        return data[:-pad_len]

