class ThreadPool:
    def __init__(self, max_workers: int = None):
        self._max_workers = max_workers or (os.cpu_count() or 1) * 5
        self._queue: queue.Queue = queue.Queue()
        self._workers: typing.List[threading.Thread] = []
        self._shutdown = False
        self._lock = threading.Lock()

    def start(self):
        for _ in range(self._max_workers):
            worker = threading.Thread(target=self._worker_loop)
            worker.daemon = True
            worker.start()
            self._workers.append(worker)

    def submit(self, func: typing.Callable, *args, **kwargs):
        future = Future()
        self._queue.put((func, args, kwargs, future))
        return future

    def _worker_loop(self):
        while not self._shutdown:
            try:
                func, args, kwargs, future = self._queue.get(timeout=0.1)
                try:
                    result = func(*args, **kwargs)
                    future.set_result(result)
                except Exception as e:
                    future.set_exception(e)
            except queue.Empty:
                continue

    def shutdown(self):
        self._shutdown = True
        for worker in self._workers:
            worker.join()

class Future:
    def __init__(self):
        self._result = None
        self._exception = None
        self._ready = False
        self._condition = threading.Condition()

    def set_result(self, result):
        with self._condition:
            self._result = result
            self._ready = True
            self._condition.notify_all()

    def set_exception(self, exception):
        with self._condition:
            self._exception = exception
            self._ready = True
            self._condition.notify_all()

    def result(self, timeout: float = None):
        with self._condition:
            if not self._ready:
                self._condition.wait(timeout)
                if not self._ready:
                    raise TimeoutError("Future did not complete in time")
            if self._exception:
                raise self._exception
            return self._result

    def is_done(self) -> bool:
        return self._ready

class AsyncLoop:
    def __init__(self):
        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(target=self._run_loop, daemon=True)

    def _run_loop(self):
        asyncio.set_event_loop(self._loop)
        self._loop.run_forever()

    def start(self):
        self._thread.start()

    def stop(self):
        self._loop.call_soon_threadsafe(self._loop.stop)
        self._thread.join()

    def run_coroutine(self, coro):
        future = asyncio.run_coroutine_threadsafe(coro, self._loop)
