class RateLimiter:
    def __init__(self, max_calls: int, period: float):
        self._max_calls = max_calls
        self._period = period
        self._calls: typing.Deque[float] = collections.deque()
        self._lock = threading.Lock()

    def allow(self) -> bool:
        with self._lock:
            now = time.time()
            while self._calls and self._calls[0] <= now - self._period:
                self._calls.popleft()
            if len(self._calls) < self._max_calls:
                self._calls.append(now)
                return True
            return False

class CircuitBreaker:
    STATES = ['CLOSED', 'OPEN', 'HALF_OPEN']

    def __init__(self, failure_threshold: int, recovery_timeout: float):
        self._failure_threshold = failure_threshold
        self._recovery_timeout = recovery_timeout
        self._state = 'CLOSED'
        self._failure_count = 0
        self._last_failure_time = None
        self._lock = threading.Lock()

    def call(self, func: typing.Callable, *args, **kwargs):
        if not self._allow_request():
            raise StateMachineError("Circuit breaker is OPEN")
        try:
            result = func(*args, **kwargs)
            self._on_success()
            return result
        except Exception as e:
            self._on_failure()
            raise e

    def _allow_request(self) -> bool:
        with self._lock:
            if self._state == 'CLOSED':
                return True
            elif self._state == 'OPEN':
                if self._last_failure_time and time.time() - self._last_failure_time > self._recovery_timeout:
                    self._state = 'HALF_OPEN'
                    return True
                return False
            elif self._state == 'HALF_OPEN':
                return True
            return False

    def _on_success(self):
        with self._lock:
            self._failure_count = 0
            self._state = 'CLOSED'

    def _on_failure(self):
        with self._lock:
            self._failure_count += 1
            self._last_failure_time = time.time()
            if self._failure_count >= self._failure_threshold:
                self._state = 'OPEN'

