class HttpResponse:
    def __init__(self, status_code: int = 200, body: str = "", headers: typing.Dict[str, str] = None):
        self.status_code = status_code
        self.body = body
        self.headers = headers if headers else {}
        self._cookies = http.cookies.SimpleCookie()

    def set_cookie(self, name: str, value: str, **kwargs):
        self._cookies[name] = value
        for k, v in kwargs.items():
            self._cookies[name][k] = v

    def to_bytes(self) -> bytes:
        status_text = self._get_status_text()
        response_line = f"HTTP/1.1 {self.status_code} {status_text}\r\n"
        headers_lines = []
        for name, value in self.headers.items():
            headers_lines.append(f"{name}: {value}")
        for cookie in self._cookies.values():
            headers_lines.append(f"Set-Cookie: {cookie.OutputString()}")
        headers_block = "\r\n".join(headers_lines) + "\r\n"
        blank_line = "\r\n"
        return (response_line + headers_block + blank_line + self.body).encode('utf-8')

    def _get_status_text(self) -> str:
        codes = {
            200: 'OK',
            201: 'Created',
            204: 'No Content',
            301: 'Moved Permanently',
            302: 'Found',
            400: 'Bad Request',
            401: 'Unauthorized',
            403: 'Forbidden',
            404: 'Not Found',
            500: 'Internal Server Error',
            503: 'Service Unavailable'
        }
        return codes.get(self.status_code, 'Unknown')

